import { useAgent, UseAgentUpdate } from "@copilotkit/react-core/v2";

const { agent } = useAgent({
  agentId: "shared-state-read-write",
  updates: [UseAgentUpdate.OnStateChanged],
});

// READ — the UI re-renders whenever the agent writes state
const notes = agent.state?.notes ?? [];

// WRITE — every edit in your UI lands in agent state
agent.setState({ preferences: next, notes });

import { useComponent } from "@copilotkit/react-core/v2";

useComponent({
  name: "render_bar_chart",
  description: "Display a bar chart with labeled numeric values.",
  parameters: barChartPropsSchema, // zod — validated before it renders
  render: BarChart,                // ordinary React, knows nothing about agents
});

import { useRenderTool } from "@copilotkit/react-core/v2";
import { z } from "zod";

useRenderTool({
  name: "research_agent",
  parameters: z.object({ task: z.string() }),
  render: ({ parameters, status, result }) => (
    <SubAgentActivityCard
      subAgent="research_agent"
      task={parameters?.task}
      status={status} // inProgress → executing → complete
      result={result}
    />
  ),
}, []);

const channel = createChannel({
  name: required("CHANNEL_CODE"),
  identifyUser: "platform",
  agent: makeAgent,      // the agent you already built
  showToolStatus: true,  // tool progress shows in the thread
});

import { useFrontendTool } from "@copilotkit/react-core/v2";
import { z } from "zod";

useFrontendTool({
  name: "request_user_approval",
  description: "Ask the operator to approve or reject an action.",
  parameters: z.object({ message: z.string(), context: z.string().optional() }),
  handler: ({ message, context }) =>
    // resolves when the operator clicks Approve or Reject in your modal
    new Promise<{ approved: boolean; reason?: string }>((resolve) =>
      setDialog({ open: true, pending: { message, context }, resolve }),
    ),
});
